-- ============================================================
-- COMPICK 실제 상품 데이터 INSERT/MERGE
-- 원본: compick_products.csv
-- 상품 수: 543개
-- stock_quantity는 원본에 없으므로 개발 기본값 10을 사용한다.
-- rating_count를 인기 상품 정렬 기준으로 사용한다.
-- ============================================================

-- 기존 PRODUCT 테이블을 사용하는 경우 최초 한 번만 실행한다.
-- 이미 rating_count가 있다면 아래 두 ALTER TABLE 문은 제외하고 실행한다.
/*ALTER TABLE PRODUCT
    ADD (rating_count NUMBER(10) DEFAULT 0 NOT NULL);

ALTER TABLE PRODUCT
    ADD CONSTRAINT ck_product_rating_count
    CHECK (rating_count >= 0); */

-- 카테고리: 이미 존재하면 건너뛴다.
MERGE INTO CATEGORY target
USING (SELECT 'CPU' AS category_name FROM DUAL) source
ON (target.category_name = source.category_name)
WHEN NOT MATCHED THEN
    INSERT (category_name) VALUES (source.category_name);

MERGE INTO CATEGORY target
USING (SELECT 'CPU_COOLER' AS category_name FROM DUAL) source
ON (target.category_name = source.category_name)
WHEN NOT MATCHED THEN
    INSERT (category_name) VALUES (source.category_name);

MERGE INTO CATEGORY target
USING (SELECT 'MAINBOARD' AS category_name FROM DUAL) source
ON (target.category_name = source.category_name)
WHEN NOT MATCHED THEN
    INSERT (category_name) VALUES (source.category_name);

MERGE INTO CATEGORY target
USING (SELECT 'RAM' AS category_name FROM DUAL) source
ON (target.category_name = source.category_name)
WHEN NOT MATCHED THEN
    INSERT (category_name) VALUES (source.category_name);

MERGE INTO CATEGORY target
USING (SELECT 'GPU' AS category_name FROM DUAL) source
ON (target.category_name = source.category_name)
WHEN NOT MATCHED THEN
    INSERT (category_name) VALUES (source.category_name);

MERGE INTO CATEGORY target
USING (SELECT 'STORAGE' AS category_name FROM DUAL) source
ON (target.category_name = source.category_name)
WHEN NOT MATCHED THEN
    INSERT (category_name) VALUES (source.category_name);

MERGE INTO CATEGORY target
USING (SELECT 'POWER_SUPPLY' AS category_name FROM DUAL) source
ON (target.category_name = source.category_name)
WHEN NOT MATCHED THEN
    INSERT (category_name) VALUES (source.category_name);

MERGE INTO CATEGORY target
USING (SELECT 'CASE' AS category_name FROM DUAL) source
ON (target.category_name = source.category_name)
WHEN NOT MATCHED THEN
    INSERT (category_name) VALUES (source.category_name);

-- 상품 데이터

-- 1. AMD Ryzen 7 9800X3D
MERGE INTO PRODUCT target
USING (
    SELECT category_id
      FROM CATEGORY
     WHERE category_name = 'CPU'
) source
ON (
       target.category_id = source.category_id
   AND target.brand = 'AMD'
   AND target.product_name = 'AMD Ryzen 7 9800X3D'
   AND target.model_name = 'AMD Ryzen 7 9800X3D [AM5]'
)
WHEN MATCHED THEN
    UPDATE SET
        target.price = 575600,
        target.rating_count = 423,
        target.stock_quantity = 10,
        target.product_description = 'AMD Ryzen 7 9800X3D CPU 상품의 상세 사양과 호환성 정보를 확인할 수 있습니다.',
        target.image_url = 'https://cdna.pcpartpicker.com/static/forever/images/product/7e2d17b7b777f8b56e1b5119aa97be20.256p.jpg',
        target.sales_status = 'ON_SALE',
        target.socket_type = 'AM5',
        target.memory_type = NULL,
        target.form_factor = NULL,
        target.power_consumption = 120,
        target.gpu_length_mm = NULL,
        target.max_gpu_length_mm = NULL,
        target.power_capacity_watt = NULL,
        target.spec_json = '{"Core Clock": "4.7 GHz", "Boost Clock": "5.2 GHz", "Socket": "AM5", "Core Count": "8", "Microarchitecture": "Zen 5", "TDP": "120 W"}',
        target.updated_at = SYSTIMESTAMP
WHEN NOT MATCHED THEN
    INSERT (
        category_id, product_name, brand, model_name, price,
        rating_count, stock_quantity, product_description, image_url,
        sales_status, socket_type, memory_type, form_factor,
        power_consumption, gpu_length_mm, max_gpu_length_mm,
        power_capacity_watt, spec_json
    ) VALUES (
        source.category_id, 'AMD Ryzen 7 9800X3D',
        'AMD', 'AMD Ryzen 7 9800X3D [AM5]',
        575600, 423, 10,
        'AMD Ryzen 7 9800X3D CPU 상품의 상세 사양과 호환성 정보를 확인할 수 있습니다.', 'https://cdna.pcpartpicker.com/static/forever/images/product/7e2d17b7b777f8b56e1b5119aa97be20.256p.jpg',
        'ON_SALE', 'AM5',
        NULL, NULL,
        120,
        NULL,
        NULL,
        NULL,
        '{"Core Clock": "4.7 GHz", "Boost Clock": "5.2 GHz", "Socket": "AM5", "Core Count": "8", "Microarchitecture": "Zen 5", "TDP": "120 W"}'
    );

